from pathlib import Path

path = Path('.github/workflows/release.yml')
text = path.read_text(encoding='utf-8')
old = '''          ### v1.8.1 수정
          - 퀘스트 진행 중 상태를 명시적으로 시작한 퀘스트에만 적용
          - 요구 레벨과 선행 퀘스트 조건 판정 강화
          - 대체 가능한 요구 아이템을 하나의 선택 묶음과 공통 수량으로 표시
          - 필요한 아이템 세부 분류를 공식 한글 범주로 정리
          - 탄약 구경 선택을 드롭다운으로 변경하고 전체 다크 테마 적용
          - 탄약 표를 방탄 효율이 낮은 순서부터 정렬하고 효율 셀 표기 간소화
          - 탄약 입수 경로를 레이드, 제작, 상인 레벨 형식으로 통일
          - 심각한 오류가 보고된 스캐너 기능과 관련 런타임 의존성 제거; 스캐너 탭만 유지
'''
new = '''          ### v1.8.2 수정
          - `수주 가능` 상태를 제거하고 시작 조건을 충족한 퀘스트를 자동으로 진행 중 처리
          - 퀘스트 상인·지도, 지도 탭 지도, 아이템 종류 드롭다운을 지정된 순서로 고정
          - 아이템 종류를 무기부터 특수까지 16개 한글 대분류로 통합
          - 범위 제출 요구를 개별 아이템 행의 묶음으로 표시하고 묶음 보유량 합산 완료 처리
          - 범위 제출 재고를 퀘스트·목표별로 분리하여 특정 아이템 제출 재고와 독립 계산
          - 탄종 드롭다운의 내부 코드·탄약 수 표기를 제거하고 공식적인 한글 명칭으로 표시
          - 탄약 표와 표시 설정 버튼을 전체 앱의 다크 테마 디자인으로 통일
          - 방탄 등급 효율을 숫자만 표시하고 효율 합산값 오름차순으로만 고정 정렬
          - 모든 드롭다운의 가장자리 마우스 호버 자동 스크롤을 제거
'''
if text.count(old) != 1:
    raise RuntimeError(f'release note block count: {text.count(old)}')
path.write_text(text.replace(old, new, 1), encoding='utf-8', newline='')
print('v1.8.2 release notes applied')
